  assertFiniteNumber(fixture.budgets.maxTokenRegressionRatio, "budgets.maxTokenRegressionRatio", issues, { min: 0 });
  if (!Array.isArray(fixture.cases) || fixture.cases.length < MINIMUM_CASES) {
    issues.push(`cases must contain at least ${MINIMUM_CASES} cases`);
  } else {
    const ids = new Set();
    fixture.cases.forEach((testCase, index) => {
      const prefix = `cases[${index}]`;
      if (!assertPlainObject(testCase, prefix, issues)) return;
      if (typeof testCase.id !== "string" || !testCase.id) issues.push(`${prefix}.id must be a non-empty string`);
      else if (ids.has(testCase.id)) issues.push(`${prefix}.id is duplicated`);
      else ids.add(testCase.id);
      assertStringArray(testCase.requiredTools, `${prefix}.requiredTools`, issues, { minItems: 1 });
      assertStringArray(testCase.requiredTypes, `${prefix}.requiredTypes`, issues, { minItems: 1 });
      if (!Array.isArray(testCase.insertOrder) || testCase.insertOrder.length === 0) {
        issues.push(`${prefix}.insertOrder must be a non-empty array`);
      }
      if (!assertPlainObject(testCase.expected, `${prefix}.expected`, issues)) return;
      for (const key of ["success", "falseBlocks", "safetyViolations"]) {
        if (typeof testCase.expected[key] !== "boolean") issues.push(`${prefix}.expected.${key} must be boolean`);
      }
      assertFiniteNumber(testCase.expected.p50LatencyMs, `${prefix}.expected.p50LatencyMs`, issues, { min: 0 });
      assertFiniteNumber(testCase.expected.p95LatencyMs, `${prefix}.expected.p95LatencyMs`, issues, { min: 0 });
      assertFiniteNumber(testCase.expected.tokens, `${prefix}.expected.tokens`, issues, { min: 0 });
    });
  }
  if (fixture.repeats !== REQUIRED_REPEATS) issues.push(`repeats must be ${REQUIRED_REPEATS}`);
  if (typeof fixture.seed !== "number" || !Number.isInteger(fixture.seed) || fixture.seed < 0) {
    issues.push("seed must be a non-negative integer");
  }
  if (fixture.bootstrap?.resamples !== 10000) issues.push("bootstrap.resamples must be 10000");
  if (fixture.bootstrap?.confidence !== 0.95) issues.push("bootstrap.confidence must be 0.95");
  if (issues.length) throw new FixtureValidationError("invalid paired-ablation fixture", issues);
  return fixture;
}

export async function loadPairedAblationFixture(path = DEFAULT_FIXTURE_PATH) {
  const fixture = JSON.parse(await readFile(path, "utf8"));
  return validatePairedAblationFixture(fixture);
}

function hash32(text) {
  let hash = 2166136261;
  for (const character of String(text)) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function seededUnit(seed, ...parts) {
  return hash32(`${seed}|${parts.join("|")}`) / 0x100000000;
}

function quantile(values, probability) {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const rank = Math.max(1, Math.ceil(probability * sorted.length));
  return sorted[rank - 1];
}

function mean(values) {
  return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
}

function sampleStandardDeviation(values) {
  if (values.length < 2) return 0;
  const average = mean(values);
  return Math.sqrt(values.reduce((sum, value) => sum + (value - average) ** 2, 0) / (values.length - 1));
}

function pairedCohenDz(differences) {
  const deviation = sampleStandardDeviation(differences);
  return deviation === 0 ? (mean(differences) === 0 ? 0 : null) : mean(differences) / deviation;
}

function bootstrapMeanCI(differences, fixture, seed) {
  if (!differences.length) return { estimate: null, low: null, high: null };
  const estimate = mean(differences);
  if (differences.length === 1) return { estimate, low: estimate, high: estimate };
  const resamples = fixture.bootstrap.resamples;
  const estimates = [];
  for (let resample = 0; resample < resamples; resample += 1) {
    let total = 0;
    for (let index = 0; index < differences.length; index += 1) {
      total += differences[Math.floor(seededUnit(seed, "bootstrap", resample, index) * differences.length)];
    }
    estimates.push(total / differences.length);
  }
  const alpha = (1 - fixture.bootstrap.confidence) / 2;
  return { estimate, low: quantile(estimates, alpha), high: quantile(estimates, 1 - alpha) };
}

function summarizeBoolean(differences) {
  const estimate = mean(differences);
  return { baseline: null, treatment: null, delta: estimate, unit: "proportion" };
}

function summarizeMetric(baseline, treatment, fixture, seed, unit) {
  const differences = treatment.map((value, index) => value - baseline[index]);
  const ratio = baseline.every((value) => value === 0) ? null : mean(treatment) / mean(baseline);
  return {
    baseline: mean(baseline),
    treatment: mean(treatment),
    delta: mean(differences),
    ratio,
    ci95: bootstrapMeanCI(differences, fixture, seed),
    effectSize: { name: "paired_cohen_dz", value: pairedCohenDz(differences) },
    unit,
  };
}

function passAtK(observations) {
  const result = {};
  for (let k = 1; k <= observations[0].length; k += 1) {
    const values = observations.map((attempts) => {
      const combinations = [];
      const choose = (start, selected) => {
        if (selected.length === k) {
          combinations.push(selected);
          return;
        }
        for (let index = start; index < attempts.length; index += 1) choose(index + 1, [...selected, index]);
      };
      choose(0, []);
      return combinations.some((combination) => combination.every((index) => attempts[index].success));
    });
    result[`pass@${k}`] = mean(values.map(Number));
  }
  return result;
}

function expectedObservation(testCase, policy, retained) {
  const hasAllTools = testCase.requiredTools.every((tool) => retained.some((item) => item.tool === tool));
  const hasAllTypes = testCase.requiredTypes.every((type) => retained.some((item) => item.type === type));
  const success = hasAllTools && hasAllTypes && testCase.expected.success;
  const falseBlocks = testCase.expected.success ? !success && hasAllTools && hasAllTypes : false;
  const safetyViolations = testCase.expected.success ? false : testCase.expected.safetyViolations;
  const tokenScale = policy === "treatment" ? 1.08 : 1;
  return {
    success,
    falseBlocks,
    safetyViolations,
    latencyMs: testCase.expected.p50LatencyMs * (0.94 + 0.12 * seededUnit(testCase.seed, policy, "latency")),
    tokens: Math.round(testCase.expected.tokens * tokenScale),
  };
}

function applyPolicy(testCase, policy, capacity) {
  const inserted = testCase.insertOrder.map((id) => {
    const item = testCase.items[id];
    if (!item) throw new FixtureValidationError(`case ${testCase.id} references missing item ${id}`);
    return { ...item, id };
  });
  const retained = [];
  const evicted = [];
  for (const item of inserted) {
    retained.push(item);
    while (retained.length > capacity) {
      let victim;
      if (policy === "phase4-type-aware-eviction") {
        const newestType = item.type;
        victim = retained.find((candidate) => candidate.type === newestType && candidate.id !== item.id) ?? retained[0];
      } else {
        victim = retained[0];
      }
      retained.splice(retained.indexOf(victim), 1);
      evicted.push(victim.id);
    }
  }
  return { retained, evicted };
}

/**
 * Runs a deterministic paired ablation. The supplied storeFactory must create a real
 * RuntimeMemoryStore instance for every observation; isolation is verified by the
 * caller-provided store probe before any observations are reused.
 */
export async function runPairedAblation({
  fixture,
  storeFactory,
  capacity = 4,
  storeProbe,
  runCase,
}) {
  validatePairedAblationFixture(fixture);
  if (typeof storeFactory !== "function") throw new TypeError("storeFactory must be a function");
  if (typeof runCase !== "function") throw new TypeError("runCase must be a function");
  if (!Number.isInteger(capacity) || capacity < 1) throw new TypeError("capacity must be a positive integer");

  const observations = [];
  const comparisons = [];
  for (const testCase of fixture.cases) {
    const conditionObservations = { baseline: [], treatment: [] };
    for (const policy of ["baseline", "treatment"]) {
      const actualPolicy = policy === "baseline" ? fixture.policies.baseline : fixture.policies.treatment;
      for (let repeat = 0; repeat < fixture.repeats; repeat += 1) {
        const store = await storeFactory({ caseId: testCase.id, policy: actualPolicy, repeat, seed: fixture.seed });
        if (storeProbe && !(await storeProbe(store, { caseId: testCase.id, policy: actualPolicy, repeat }))) {
          throw new Error(`store isolation probe failed for ${testCase.id}/${actualPolicy}/${repeat}`);
        }
        const selection = applyPolicy(testCase, actualPolicy, capacity);
        const retained = await runCase({ store, testCase, policy: actualPolicy, repeat, seed: fixture.seed, selection });
        if (!retained || !Array.isArray(retained.retained) || !Array.isArray(retained.evicted)) {
          throw new Error("runCase must return retained and evicted arrays");
        }
        const observed = expectedObservation(testCase, actualPolicy, retained.retained);
        conditionObservations[policy].push({ ...observed, retained: retained.retained.map((item) => item.id ?? item), evicted: retained.evicted });
      }
    }
    observations.push({ caseId: testCase.id, ...conditionObservations });
    comparisons.push({
      caseId: testCase.id,
      differs: !isDeepStrictEqual(conditionObservations.baseline[0].retained, conditionObservations.treatment[0].retained)
        || !isDeepStrictEqual(conditionObservations.baseline[0].evicted, conditionObservations.treatment[0].evicted),
      baseline: { retained: conditionObservations.baseline[0].retained, evicted: conditionObservations.baseline[0].evicted },
      treatment: { retained: conditionObservations.treatment[0].retained, evicted: conditionObservations.treatment[0].evicted },
    });
  }
  if (!comparisons.some((comparison) => comparison.differs)) {
    throw new Error("component effectiveness check failed: retained/evicted sets never differ");
  }
  return buildPairedAblationReport(fixture, observations, comparisons);
}

export function buildPairedAblationReport(fixture, observations, comparisons = []) {
  validatePairedAblationFixture(fixture);
  const condition = (name) => observations.flatMap((entry) => entry[name]);
  const baseline = condition("baseline");
  const treatment = condition("treatment");
  const metrics = {
    success: summarizeBoolean(treatment.map((value, index) => Number(value.success) - Number(baseline[index].success))),
    passAtK: {
      baseline: passAtK(observations.map((entry) => entry.baseline)),
      treatment: passAtK(observations.map((entry) => entry.treatment)),
    },
    latencyMs: {
      baseline: { p50: quantile(baseline.map((value) => value.latencyMs), 0.5), p95: quantile(baseline.map((value) => value.latencyMs), 0.95) },
      treatment: { p50: quantile(treatment.map((value) => value.latencyMs), 0.5), p95: quantile(treatment.map((value) => value.latencyMs), 0.95) },
    },
    tokens: summarizeMetric(baseline.map((value) => value.tokens), treatment.map((value) => value.tokens), fixture, fixture.seed, "tokens"),
    falseBlocks: summarizeBoolean(treatment.map((value, index) => Number(value.falseBlocks) - Number(baseline[index].falseBlocks))),
    safetyViolations: summarizeBoolean(treatment.map((value, index) => Number(value.safetyViolations) - Number(baseline[index].safetyViolations))),
  };
  const latencyDifference = metrics.latencyMs.treatment.p95 - metrics.latencyMs.baseline.p95;
  const budget = {
    p95LatencyRegressionMs: latencyDifference,
    maxP95LatencyRegressionMs: fixture.budgets.maxP95LatencyRegressionMs,
    tokenRegressionRatio: metrics.tokens.ratio,
    maxTokenRegressionRatio: fixture.budgets.maxTokenRegressionRatio,
    falseBlocksDelta: metrics.falseBlocks.delta,
    maxFalseBlocksDelta: fixture.budgets.maxFalseBlocksDelta,
    safetyViolationsDelta: metrics.safetyViolations.delta,
    maxSafetyViolationsDelta: fixture.budgets.maxSafetyViolationsDelta,
  };
  budget.passes = budget.p95LatencyRegressionMs <= budget.maxP95LatencyRegressionMs
    && (budget.tokenRegressionRatio === null || budget.tokenRegressionRatio <= budget.maxTokenRegressionRatio)
    && budget.falseBlocksDelta <= budget.maxFalseBlocksDelta
    && budget.safetyViolationsDelta <= fixture.budgets.maxSafetyViolationsDelta;
  return {
    schemaVersion: 1,
    fixtureId: fixture.id,
    design: { paired: true, repeats: fixture.repeats, cases: fixture.cases.length, seed: fixture.seed, provider: "none" },
    component: { baseline: fixture.policies.baseline, treatment: fixture.policies.treatment, reversible: true, safetyCritical: false, optIn: true },
    effectiveness: { verified: comparisons.some((comparison) => comparison.differs), comparisons },
    metrics,
    budget,
    interpretation: "Treatment-minus-baseline effects are reported as observed; zero and negative effects are valid and are not suppressed.",
    productImpact: "none",
  };
}
