    maxTokenRegressionRatio: number;
  };
  bootstrap: { resamples: 10000; confidence: 0.95 };
  cases: PairedAblationTestCase[];
}

export class FixtureValidationError extends Error {
  readonly issues: string[];
  constructor(message: string, issues?: string[]);
}

export interface PairedAblationObservation {
  success: boolean;
  falseBlocks: boolean;
  safetyViolations: boolean;
  latencyMs: number;
  tokens: number;
  retained: Array<string | PairedAblationFixtureItem>;
  evicted: string[];
}

export interface PairedAblationReport {
  schemaVersion: 1;
  fixtureId: string;
  design: { paired: true; repeats: 3; cases: number; seed: number; provider: "none" };
  component: { baseline: string; treatment: string; reversible: true; safetyCritical: false; optIn: true };
  effectiveness: { verified: boolean; comparisons: unknown[] };
  metrics: Record<string, unknown>;
  budget: Record<string, unknown> & { passes: boolean };
  interpretation: string;
  productImpact: "none";
}

export const DEFAULT_FIXTURE_PATH: string;
export const REQUIRED_REPEATS: 3;
export const MINIMUM_CASES: 20;

export function validatePairedAblationFixture(fixture: PairedAblationFixture): PairedAblationFixture;
export function loadPairedAblationFixture(path?: string): Promise<PairedAblationFixture>;
export function buildPairedAblationReport(
  fixture: PairedAblationFixture,
  observations: Array<{ baseline: PairedAblationObservation[]; treatment: PairedAblationObservation[] }>,
  comparisons?: unknown[],
): PairedAblationReport;

export function runPairedAblation(options: {
  fixture: PairedAblationFixture;
  storeFactory: (context: { caseId: string; policy: string; repeat: number; seed: number }) => unknown | Promise<unknown>;
  capacity?: number;
  storeProbe?: (store: unknown, context: { caseId: string; policy: string; repeat: number }) => boolean | Promise<boolean>;
  runCase: (context: {
    store: unknown;
    testCase: PairedAblationTestCase;
    policy: string;
    repeat: number;
    seed: number;
    selection: { retained: PairedAblationFixtureItem[]; evicted: string[] };
  }) => PairedAblationObservation | Promise<PairedAblationObservation>;
}): Promise<PairedAblationReport>;
