export interface PairedAblationTestCase {
  id: string;
  seed: number;
  requiredTools: string[];
  requiredTypes: string[];
  insertOrder: string[];
  items: Record<string, PairedAblationFixtureItem>;
  expected: {
    success: boolean;
    p50LatencyMs: number;
    p95LatencyMs: number;
    tokens: number;
    falseBlocks: boolean;
    safetyViolations: boolean;
  };
}

export interface PairedAblationFixture {
  id: string;
  repeats: 3;
  seed: number;
  requiredTools: string[];
  allowedProviders: ["none"];
  policies: {
    baseline: "phase4-fifo";
    treatment: "phase4-type-aware-eviction";
  };
  budgets: {
    maxFalseBlocksDelta: number;
    maxSafetyViolationsDelta: number;
    maxP95LatencyRegressionMs: number;
    maxTokenRegressionRatio: number;
  };
  bootstrap: { resamples: 10000; confidence: 0.95 };
  cases: PairedAblationTestCase[];
}

export class FixtureValidationError extends Error {
  readonly issues: string[];
  constructor(message: string, issues?: string[]);
}

export interface PairedAblationObservation {
  success: boolean;
  falseBlocks: boolean;
  safetyViolations: boolean;
  latencyMs: number;
  tokens: number;
  retained: Array<string | PairedAblationFixtureItem>;
  evicted: string[];
}

export interface PairedAblationReport {
  schemaVersion: 1;
  fixtureId: string;
  design: { paired: true; repeats: 3; cases: number; seed: number; provider: "none" };
  component: { baseline: string; treatment: string; reversible: true; safetyCritical: false; optIn: true };
  effectiveness: { verified: boolean; comparisons: unknown[] };
  metrics: Record<string, unknown>;
  budget: Record<string, unknown> & { passes: boolean };
  interpretation: string;
  productImpact: "none";
}

export const DEFAULT_FIXTURE_PATH: string;
export const REQUIRED_REPEATS: 3;
export const MINIMUM_CASES: 20;

export function validatePairedAblationFixture(fixture: PairedAblationFixture): PairedAblationFixture;
